import{_ as s,a8 as t,o as n,c as l,ah as _,K as a}from"./chunks/framework.D9VmMSku.js";import"./chunks/theme.7j9Y6pfQ.js";const C=JSON.parse('{"title":"分发优先原则","description":"","frontmatter":{"title":"分发优先原则","abstract":"消费级产品分发与产品同等重要甚至应更早布局——先用免费自然流量验证需求与共鸣，有牵引力后再叠加达人、UGC 与付费放大。","created":"2026-09-21T00:00:00.000Z","tags":["创业","增长","产品"],"type":"概念解释","related":["[[个人成长产品创业启示-MOC]]"],"reference":["[[AI personal growth app_中文]]"],"category":["💡 创业启示"]},"headers":[],"relativePath":"vault/Knowledge/Methods/分发优先原则.md","filePath":"vault/Knowledge/Methods/分发优先原则.md","lastUpdated":1790663635000}'),i={name:"vault/Knowledge/Methods/分发优先原则.md"};function p(d,e,c,m,g,h){const o=t("NolebaseGitContributors"),r=t("NolebaseGitChangelog");return n(),l("div",null,[e[0]||(e[0]=_('<h1 id="分发优先原则" tabindex="-1">分发优先原则 <a class="header-anchor" href="#分发优先原则" aria-label="Permalink to “分发优先原则”">​</a></h1><p>好产品没人看，等于没有。对消费级产品而言，<strong>分发（让对的人看到）和产品本身同等重要，甚至应更早布局</strong>。</p><p>要点：</p><ul><li>创始人若有过营销或代理背景，更应第一天就把获客当核心，而不是产品做完再想怎么卖。</li><li>早期用免费自然流量（Instagram / TikTok / Reddit）触达已经在讨论相关话题的人群，验证需求与共鸣。</li><li>有了牵引力后，再叠加达人合作、UGC 计划、付费广告来放大。</li></ul><p>反面：只打磨产品、忽略分发，再好也容易沉没。</p><p>来源：StarterStory 访谈（访问于 2026-09-21）。</p>',6)),a(o),a(r)])}const b=s(i,[["render",p]]);export{C as __pageData,b as default};
